set
  title = 'Criminology',
  goal = 'Criminology',
  summary = 'Criminology examines the nature, causes, measurement, patterns, and prevention of crime in the United States. Students study major theoretical traditions, official and survey-based crime data, individual and social risk factors, inequality, social control, victimization, violent crime, property and white-collar crime, cybercrime, drugs, gangs, juvenile delinquency, policing, punishment, corrections, reentry, technology, and evidence-based prevention. The course emphasizes theory-data-policy integration and prepares students to evaluate crime claims with rigor and ethical care.',
