values
  ('3c8d76bb-29ec-48bf-8ee0-e15948e0709c', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', null, 'topic'::public.curated_course_node_type, 'Foundations of Criminology and the American Criminal Justice Context', 'This opening unit defines criminology as the study of crime, law, deviance, social harm, criminalization, and social response. Students learn how theory, data, institutions, and policy fit together.', 0),
  ('83df0fca-6674-4316-a6ed-d3f9e569ae3a', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '3c8d76bb-29ec-48bf-8ee0-e15948e0709c', 'subtopic'::public.curated_course_node_type, 'Crime, Deviance, and Social Harm', 'The point is to distinguish legal crime from broader social harm and deviance.', 0),
  ('c3ee7b4d-2dfa-475e-b57b-09a63c2486eb', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '83df0fca-6674-4316-a6ed-d3f9e569ae3a', 'concept'::public.curated_course_node_type, 'Definitions of crime', null, 0),
