  ('f5765c4b-b402-445e-8746-ce7ca6f79633', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '18dc5113-2bb9-448d-bbcb-70b1dbc3a15f', 'concept'::public.curated_course_node_type, 'Crime control and due process', null, 1),
  ('1e05eedd-ff55-4272-b650-883f61b9c067', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '18dc5113-2bb9-448d-bbcb-70b1dbc3a15f', 'concept'::public.curated_course_node_type, 'Community and state power', null, 2),
  ('c9b1ac39-44d4-4b57-8b0d-5d7b799a2809', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '3c8d76bb-29ec-48bf-8ee0-e15948e0709c', 'subtopic'::public.curated_course_node_type, 'Criminological Imagination', 'This subtopic teaches students to connect individual cases to social structure.', 2),
  ('883ef984-06ab-49cb-9f1e-d77e546169f5', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'c9b1ac39-44d4-4b57-8b0d-5d7b799a2809', 'concept'::public.curated_course_node_type, 'Micro and macro levels', null, 0),
  ('aa7a2592-4464-424b-8295-c715b2e0074b', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'c9b1ac39-44d4-4b57-8b0d-5d7b799a2809', 'concept'::public.curated_course_node_type, 'Theory and evidence', null, 1),
  ('21e359f2-5237-4556-8a3d-41c4f4b5d454', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'c9b1ac39-44d4-4b57-8b0d-5d7b799a2809', 'concept'::public.curated_course_node_type, 'Policy consequences', null, 2),
  ('71186626-bdf9-45e6-92ee-60b21a0791bc', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', null, 'topic'::public.curated_course_node_type, 'Measuring Crime: UCR/NIBRS, NCVS, Self-Report, and Data Ethics', 'Crime measurement shapes what society thinks crime is. Students learn the strengths, limits, and ethical risks of major U.S. crime-data systems.', 1),
  ('14a2d141-033e-4553-afef-09909584111b', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '71186626-bdf9-45e6-92ee-60b21a0791bc', 'subtopic'::public.curated_course_node_type, 'Official Police Data', 'Students learn what reported crime data capture and miss.', 0),
  ('7855ec38-8117-4b36-808e-622cd83cd051', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '14a2d141-033e-4553-afef-09909584111b', 'concept'::public.curated_course_node_type, 'UCR and NIBRS', null, 0),
  ('8f912a48-55be-4d1e-875c-19ae0f1bb2a4', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '14a2d141-033e-4553-afef-09909584111b', 'concept'::public.curated_course_node_type, 'Agency participation', null, 1),
  ('b5726e6f-8ffb-4643-888a-b30fa3862c11', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '14a2d141-033e-4553-afef-09909584111b', 'concept'::public.curated_course_node_type, 'Clearance and reporting bias', null, 2),
  ('3ed30950-7889-4648-a170-8fba322dd009', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '71186626-bdf9-45e6-92ee-60b21a0791bc', 'subtopic'::public.curated_course_node_type, 'Victimization and Self-Report Data', 'The gist is to measure the dark figure of crime beyond police reports.', 1),
  ('e40689d3-937e-4fbc-9840-e574f7f2fd6e', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '3ed30950-7889-4648-a170-8fba322dd009', 'concept'::public.curated_course_node_type, 'NCVS', null, 0),
  ('4c3d9353-6ee8-49a8-bf16-b2d043a49150', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '3ed30950-7889-4648-a170-8fba322dd009', 'concept'::public.curated_course_node_type, 'Self-report surveys', null, 1),
  ('69497b08-080a-489f-988d-d41e38be311e', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '3ed30950-7889-4648-a170-8fba322dd009', 'concept'::public.curated_course_node_type, 'Underreporting and recall', null, 2),
  ('fdd717cc-b9cd-45a9-939d-bc95e63fc177', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '71186626-bdf9-45e6-92ee-60b21a0791bc', 'subtopic'::public.curated_course_node_type, 'Data Ethics and Interpretation', 'Students learn to avoid simplistic claims from incomplete data.', 2),
  ('ab8905bc-d4a0-4e3d-a24e-ef8ac632ab3a', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'fdd717cc-b9cd-45a9-939d-bc95e63fc177', 'concept'::public.curated_course_node_type, 'Base rates', null, 0),
  ('f884de6b-446d-4bec-a90b-8fcf752daef0', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'fdd717cc-b9cd-45a9-939d-bc95e63fc177', 'concept'::public.curated_course_node_type, 'Racial and geographic bias', null, 1),
  ('8aeade6e-0e69-4e7e-9f63-873ef8d390e8', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'fdd717cc-b9cd-45a9-939d-bc95e63fc177', 'concept'::public.curated_course_node_type, 'Privacy and disclosure risks', null, 2),
  ('87fa4bba-b41c-4f27-9c32-4f0baf621680', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', null, 'topic'::public.curated_course_node_type, 'Classical, Deterrence, Rational Choice, and Routine Activities Theories', 'This section studies crime as choice under constraints and opportunity. Students learn why punishment and prevention policy often begin with deterrence and opportunity.', 2),
  ('c248106a-68e2-4886-95c8-acdd157d5fe3', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '87fa4bba-b41c-4f27-9c32-4f0baf621680', 'subtopic'::public.curated_course_node_type, 'Classical School', 'Students examine the roots of legal rationality and proportional punishment.', 0),
  ('180df5e6-7cd4-42b3-b25f-7fb702345f86', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'c248106a-68e2-4886-95c8-acdd157d5fe3', 'concept'::public.curated_course_node_type, 'Beccaria', null, 0),
  ('4d890802-fe7d-47df-b6cf-f699a19b0f2f', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'c248106a-68e2-4886-95c8-acdd157d5fe3', 'concept'::public.curated_course_node_type, 'Bentham', null, 1),
  ('dc06b3ea-4952-4ca0-8036-71dd79b55c93', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'c248106a-68e2-4886-95c8-acdd157d5fe3', 'concept'::public.curated_course_node_type, 'Free will and punishment', null, 2),
  ('082735fc-515f-47ff-880c-c6ecee5d69b2', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '87fa4bba-b41c-4f27-9c32-4f0baf621680', 'subtopic'::public.curated_course_node_type, 'Deterrence and Rational Choice', 'The point is to analyze how certainty, severity, and celerity affect behavior.', 1),
  ('ab0ad575-7e6b-4c87-8372-681724cfbed3', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '082735fc-515f-47ff-880c-c6ecee5d69b2', 'concept'::public.curated_course_node_type, 'General deterrence', null, 0),
  ('b67a7a50-f811-4429-b521-101125fdce2b', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '082735fc-515f-47ff-880c-c6ecee5d69b2', 'concept'::public.curated_course_node_type, 'Specific deterrence', null, 1),
  ('e0292a1c-ad9e-4ca1-ba19-08e7aef5b777', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '082735fc-515f-47ff-880c-c6ecee5d69b2', 'concept'::public.curated_course_node_type, 'Perceived risk', null, 2),
  ('524b14b2-43fc-467f-b290-1683e0b8caea', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '87fa4bba-b41c-4f27-9c32-4f0baf621680', 'subtopic'::public.curated_course_node_type, 'Routine Activities and Opportunity', 'Students learn why crime clusters in places and routines.', 2),
  ('a9a0526f-0060-4ad0-85ed-6c47c548aa9d', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '524b14b2-43fc-467f-b290-1683e0b8caea', 'concept'::public.curated_course_node_type, 'Motivated offenders', null, 0),
  ('91545a77-91ae-4587-95f9-0d15cfe213f9', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '524b14b2-43fc-467f-b290-1683e0b8caea', 'concept'::public.curated_course_node_type, 'Suitable targets', null, 1),
  ('5a5aa20f-c1ce-48be-80f2-aab337ddac43', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '524b14b2-43fc-467f-b290-1683e0b8caea', 'concept'::public.curated_course_node_type, 'Capable guardianship', null, 2),
  ('5584c958-d5e1-4013-903e-91b94b650a5c', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', null, 'topic'::public.curated_course_node_type, 'Biological, Psychological, and Developmental Risk Factors', 'This unit covers individual-level risk without reducing crime to biology or pathology. Students learn how traits, trauma, cognition, and development interact with environment.', 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('50ed16ea-6ba8-4f6b-b084-385eb0b4c8d1', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '5584c958-d5e1-4013-903e-91b94b650a5c', 'subtopic'::public.curated_course_node_type, 'Biosocial Perspectives', 'Students learn how biological risk is studied responsibly in social context.', 0),
