  ('708aad9e-ff9b-43c3-b07a-7f7b973400ae', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '5584c958-d5e1-4013-903e-91b94b650a5c', 'subtopic'::public.curated_course_node_type, 'Psychological Theories', 'The gist is to connect cognition, personality, learning, and mental health to offending.', 1),
