  ('f811d10c-0bd9-4285-951d-a5506fc40e9f', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '708aad9e-ff9b-43c3-b07a-7f7b973400ae', 'concept'::public.curated_course_node_type, 'Trauma and disorders', null, 2),
  ('e7942dcc-c6b0-4ea7-bfad-1de0f443b021', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '5584c958-d5e1-4013-903e-91b94b650a5c', 'subtopic'::public.curated_course_node_type, 'Risk, Protection, and Ethics', 'Students learn to distinguish explanation from prediction or stigma.', 2),
  ('69b0d2a3-e4e7-424c-b323-53bf49a9e333', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'e7942dcc-c6b0-4ea7-bfad-1de0f443b021', 'concept'::public.curated_course_node_type, 'Risk factors', null, 0),
  ('994a73b5-abd2-4fbd-b844-588f11456be3', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'e7942dcc-c6b0-4ea7-bfad-1de0f443b021', 'concept'::public.curated_course_node_type, 'Protective factors', null, 1),
  ('0284a8d3-324a-4e5c-ab90-72583d92dfee', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'e7942dcc-c6b0-4ea7-bfad-1de0f443b021', 'concept'::public.curated_course_node_type, 'Labeling and misuse', null, 2),
  ('fa089167-4b1c-4a20-a43f-53c538849819', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', null, 'topic'::public.curated_course_node_type, 'Social Structure Theories: Strain, Anomie, Disorganization, and Inequality', 'Social structure theories explain crime through unequal opportunity, neighborhood conditions, and blocked goals. Students learn why place and inequality matter.', 4),
  ('64c62f52-3cd5-4d88-a62a-f1f496b0b495', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'fa089167-4b1c-4a20-a43f-53c538849819', 'subtopic'::public.curated_course_node_type, 'Strain and Anomie', 'Students learn how blocked opportunity and pressure can generate crime.', 0),
  ('df4202ee-9fb7-4ec1-9753-4ee87422b15b', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '64c62f52-3cd5-4d88-a62a-f1f496b0b495', 'concept'::public.curated_course_node_type, 'Merton', null, 0),
  ('596f2035-a99d-4710-95b3-27cace03300f', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '64c62f52-3cd5-4d88-a62a-f1f496b0b495', 'concept'::public.curated_course_node_type, 'General strain', null, 1),
  ('5866884d-6b2a-4b82-a7be-f57246eb5f55', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '64c62f52-3cd5-4d88-a62a-f1f496b0b495', 'concept'::public.curated_course_node_type, 'Coping and anger', null, 2),
  ('19fa7abd-7f7f-4a4f-bc7b-3e80e9221ebd', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'fa089167-4b1c-4a20-a43f-53c538849819', 'subtopic'::public.curated_course_node_type, 'Social Disorganization', 'The point is to understand neighborhood ecology and collective efficacy.', 1),
  ('a2f96ec1-bceb-462e-ae78-c5b07f7923f6', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '19fa7abd-7f7f-4a4f-bc7b-3e80e9221ebd', 'concept'::public.curated_course_node_type, 'Concentrated disadvantage', null, 0),
  ('ff3d2bd0-f6c0-4afd-b3b8-9754819a9db0', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '19fa7abd-7f7f-4a4f-bc7b-3e80e9221ebd', 'concept'::public.curated_course_node_type, 'Residential instability', null, 1),
  ('774ea11c-a6ce-46b1-a609-5829aa3be469', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '19fa7abd-7f7f-4a4f-bc7b-3e80e9221ebd', 'concept'::public.curated_course_node_type, 'Informal social control', null, 2),
  ('f7d6382a-cc77-4b57-99d3-dcd9a35cbb1c', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'fa089167-4b1c-4a20-a43f-53c538849819', 'subtopic'::public.curated_course_node_type, 'Inequality and Structural Violence', 'Students connect crime to race, class, segregation, and institutional access.', 2),
  ('bae4b050-fc0c-4949-b1af-683eb4a9432a', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'f7d6382a-cc77-4b57-99d3-dcd9a35cbb1c', 'concept'::public.curated_course_node_type, 'Poverty and exclusion', null, 0),
  ('5f19e06b-8497-4c91-8e5e-bb745559facf', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'f7d6382a-cc77-4b57-99d3-dcd9a35cbb1c', 'concept'::public.curated_course_node_type, 'Racial inequality', null, 1),
  ('bb354013-2795-4d15-83cd-22697248308a', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', 'f7d6382a-cc77-4b57-99d3-dcd9a35cbb1c', 'concept'::public.curated_course_node_type, 'Policy feedback loops', null, 2),
  ('8470b2b5-0aac-4cd8-9f80-3efcf9c8de84', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', null, 'topic'::public.curated_course_node_type, 'Social Process Theories: Learning, Control, Labeling, and Neutralization', 'Social process theories ask how people learn, justify, and desist from crime in interaction with others. Students focus on family, peers, schools, and identity.', 5),
  ('256913cb-869b-4185-ac8a-cffe86acac35', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '8470b2b5-0aac-4cd8-9f80-3efcf9c8de84', 'subtopic'::public.curated_course_node_type, 'Learning Theories', 'Students examine how crime is learned through groups and reinforcement.', 0),
  ('8bc3b40d-5308-4923-be0e-318e7425d03d', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '256913cb-869b-4185-ac8a-cffe86acac35', 'concept'::public.curated_course_node_type, 'Differential association', null, 0),
