  ('e4223f0b-3f59-4159-985b-f9ccaabe7733', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '256913cb-869b-4185-ac8a-cffe86acac35', 'concept'::public.curated_course_node_type, 'Peer networks', null, 2),
