  ('a510f2a7-1e2b-4f58-a53f-a3216ce6c857', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '59d032ee-7532-4fc7-80fc-6d14a49102a3', 'concept'::public.curated_course_node_type, 'Social bonds', null, 0),
  ('208631e6-e7e5-45ce-8b2b-5d4d5f221267', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '59d032ee-7532-4fc7-80fc-6d14a49102a3', 'concept'::public.curated_course_node_type, 'Self-control', null, 1),
  ('36b99fd5-0cad-4a20-bba3-7d519c83efe8', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '59d032ee-7532-4fc7-80fc-6d14a49102a3', 'concept'::public.curated_course_node_type, 'Informal controls', null, 2),
