  ('3ce9eea7-def7-42b9-a0a7-e52cbc6e10bc', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '99435bde-3824-4d09-a620-c23137a63f26', 'concept'::public.curated_course_node_type, 'Stigma', null, 0),
  ('cb7d251e-24a9-4027-b695-1972feafce7f', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '99435bde-3824-4d09-a620-c23137a63f26', 'concept'::public.curated_course_node_type, 'Secondary deviance', null, 1),
  ('ec7f141a-e502-44fc-ae2e-e1f775f2a10f', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '99435bde-3824-4d09-a620-c23137a63f26', 'concept'::public.curated_course_node_type, 'Techniques of neutralization', null, 2),
  ('44e230c1-8a5e-4a05-8c46-d0965453eb96', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', null, 'topic'::public.curated_course_node_type, 'Critical, Conflict, Feminist, Queer, and Intersectional Criminology', 'This unit asks who defines crime and whose harms count. Students learn how power, inequality, and identity shape lawmaking and enforcement.', 6),
  ('84ebfe15-c094-4c80-82ee-a7e316ec6028', 'c6d7e8f9-0a1b-4d36-9e56-7f8a9b0c1d66', '44e230c1-8a5e-4a05-8c46-d0965453eb96', 'subtopic'::public.curated_course_node_type, 'Conflict and Critical Theory', 'Students examine crime law as a product of power and social conflict.', 0);
